.atlsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #3a2f25;
    background: linear-gradient(165deg, #fdf6ec 0%, #f6ead4 55%, #f0dfc0 100%);
    border-radius: 18px;
}

.atlsim-container * {
    box-sizing: border-box;
}

.atlsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #8a4b24 0%, #b9712f 48%, #c69a3e 100%);
    color: #fff7e9;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #a35d28;
    box-shadow: 0 12px 30px rgba(120, 70, 30, 0.30);
}

.atlsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fff7e9;
}

.atlsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #fff1d6;
    background: rgba(255, 241, 214, 0.16);
    border: 1px solid rgba(255, 241, 214, 0.35);
    padding: 5px 14px;
    border-radius: 999px;
}

.atlsim-subtitle {
    margin: 12px auto 0;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #fbe9cf;
}

.atlsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5640;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.atlsim-period-counter #currentDay,
.atlsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b9712f;
}

.atlsim-round-name {
    background: rgba(185, 113, 47, 0.16);
    color: #8a4b24;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.atlsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a3331f;
    background: rgba(199, 70, 45, 0.12);
    border: 1px solid rgba(199, 70, 45, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.atlsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.atlsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7d6b8;
    box-shadow: 0 6px 16px rgba(140, 100, 50, 0.12);
    border-top: 4px solid #b9712f;
}

.atlsim-card-reach { border-top-color: #2f7d5b; }
.atlsim-card-spoil { border-top-color: #c7462d; }
.atlsim-card-cap { border-top-color: #d39a2b; }
.atlsim-card-contrib { border-top-color: #8a4b24; }

.atlsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8c7355;
}

.atlsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3a2f25;
    font-variant-numeric: tabular-nums;
}

.atlsim-card-reach .atlsim-value { color: #2f7d5b; }
.atlsim-card-spoil .atlsim-value { color: #c7462d; }
.atlsim-card-cap .atlsim-value { color: #c08524; }
.atlsim-card-contrib .atlsim-value { color: #8a4b24; }

.atlsim-sublabel {
    font-size: 0.76rem;
    color: #9b8265;
    line-height: 1.35;
}

.atlsim-spoil-good { border-top-color: #2f7d5b; }
.atlsim-spoil-good .atlsim-value { color: #2f7d5b; }
.atlsim-spoil-bad { border-top-color: #c7462d; }
.atlsim-spoil-bad .atlsim-value { color: #c7462d; }

.atlsim-contrib-positive .atlsim-value { color: #2f7d5b; }
.atlsim-contrib-negative .atlsim-value { color: #c7462d; }

.atlsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #e7d6b8;
    color: #6b5640;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.atlsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #8a4b24;
}

.atlsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #b9712f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(140, 100, 50, 0.10);
}

.atlsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.atlsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #8a4b24;
    margin-bottom: 6px;
}

.atlsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4d4032;
}

.atlsim-briefing-text strong { color: #b9712f; }
.atlsim-briefing-text em { color: #c7462d; font-style: italic; }

.atlsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e7d6b8;
    box-shadow: 0 6px 16px rgba(140, 100, 50, 0.10);
}

.atlsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #8a4b24;
    border-bottom: 2px solid #efe1c8;
    padding-bottom: 8px;
}

.atlsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5a4a37;
    margin: 14px 0 6px;
}

.atlsim-container select,
.atlsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d9c3a0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #3a2f25;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.atlsim-container select:focus,
.atlsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b9712f;
    box-shadow: 0 0 0 3px rgba(185, 113, 47, 0.18);
}

.atlsim-container select option {
    background-color: #fffdf8;
    color: #3a2f25;
}

.atlsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b9712f;
}

.atlsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5640;
    margin-top: 4px;
}

.atlsim-range-readout span:nth-child(2) {
    color: #b9712f;
    font-weight: 800;
}

.atlsim-hint {
    font-size: 0.8rem;
    color: #9b8265;
    margin-top: 4px;
    line-height: 1.4;
}

.atlsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.atlsim-container .btn-primary {
    background: linear-gradient(135deg, #8a4b24 0%, #c69a3e 100%);
    border: none;
    color: #fff7e9;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(138, 75, 36, 0.35);
}

.atlsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.atlsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d9c3a0;
    color: #8c7355;
    background: transparent;
}

.atlsim-coach {
    background: linear-gradient(160deg, #2c4a3a 0%, #244033 100%);
    color: #ecf6ee;
    border: 1px solid #1f3a2e;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(40, 70, 50, 0.25);
}

.atlsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9fd9b6;
    margin-bottom: 8px;
}

.atlsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.atlsim-coach-body strong { color: #f2d089; }
.atlsim-coach-body em { color: #f0a98e; font-style: italic; }

.atlsim-history,
.atlsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7d6b8;
    box-shadow: 0 6px 16px rgba(140, 100, 50, 0.10);
}

.atlsim-history h3,
.atlsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #8a4b24;
}

.atlsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4d4032;
}

.atlsim-container table#usfHistoryTable th {
    background: #f6ead4;
    color: #8a4b24;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3cfa9;
}

.atlsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe1c8;
    color: #4d4032;
}

.atlsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fcf4e4;
}

.atlsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .atlsim-container {
        padding: 14px;
    }
    .atlsim-header h1 {
        font-size: 1.7rem;
    }
    .atlsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .atlsim-value {
        font-size: 2rem;
    }
    .atlsim-clock {
        margin-left: 0;
    }
    .atlsim-period-counter {
        font-size: 0.88rem;
    }
    .atlsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .atlsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .atl-cm-*, Atlântico green/gold) ── */
.atl-cm { margin-top: 8px; }
.atl-cm-incomplete { text-align: center; color: #4a5a4f; font-size: 1rem; padding: 18px; }
.atl-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.atl-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0f5132 0%, #1a7a4a 55%, #c9a227 140%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(15, 81, 50, 0.28); }
.atl-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.atl-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.atl-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0dca0; }
.atl-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #d8e4dc; border-left: 5px solid #1a7a4a; border-radius: 14px; padding: 16px 20px; }
.atl-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5b6b60; }
.atl-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #0f5132; line-height: 1.15; }
.atl-cm-section { margin-bottom: 16px; }
.atl-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5b6b60; margin-bottom: 8px; }
.atl-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.atl-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.atl-cm-ok { background: #e3f3ea; color: #0f5132; border-color: #a9d7bd; }
.atl-cm-no { background: #fdecea; color: #a12a1f; border-color: #f2c2bc; }
.atl-cm-ico { font-weight: 800; }
.atl-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.atl-cm-kpi { background: #f5f8f6; border: 1px solid #dce7e0; border-radius: 12px; padding: 12px 14px; text-align: center; }
.atl-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #0f5132; }
.atl-cm-kpi-lbl { margin-top: 2px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: #5b6b60; }
.atl-cm-kpi-sub { margin-top: 2px; font-size: 0.68rem; color: #8a978e; }
.atl-cm-insights { margin: 0; padding-left: 18px; }
.atl-cm-insights li { font-size: 0.9rem; color: #33413a; margin-bottom: 6px; line-height: 1.45; }

