(function() {
    'use strict';

    class AtlanticoAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Manage Across Markets`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Atlântico Foods · Kenya entry).
            this.PROGRAMME_BUDGET = 18;     // EUR 18M / shown US$18M envelope over 3 yrs
            this.GAP = 5.6;                 // US$5.6M revenue gap (target 9.0 vs run-rate 3.4)
            this.TARGET = 9.0;             // US$9.0M Year-1 target
            this.INFORMAL_SHARE = 68;       // 68% of grocery volume in dukas/open markets
            this.EXPAT_COST = 0.22;         // US$220K each per year
            this.JV_CAPITAL = 7;            // US$7M Atlântico capital for the JV
            this.DIST_MARGIN_GIVEAWAY = 14; // 14% margin given away to the distributor

            // Concept truths (the adapt-not-export thesis).
            this.TRUE_LENS = `adapt`;
            this.TRUE_ROOT = `channel`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    reach: 11,              // % of target outlets served (starts at 11%)
                    spoilage: 22,           // % chilled spoilage (lower better; starts 22%, Iberia 3%)
                    capacity: 18,           // local management strength & succession (0–100)
                    contribution: 3.4,      // US$M annual run-rate (starts 3.4, target 9.0)
                    budgetUsed: 0,          // US$M of the programme envelope committed
                    payback: 0,             // 3-year payback score (0–100), revealed in R4
                    coldSolved: false,
                    expatTrap: false,
                    partnerMisaligned: false,
                    reachHistory: [11],
                    spoilHistory: [22],
                    capHistory: [18],
                    contribHistory: [3.4],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately copy-paste / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    lens: `execution`,
                    root: `capability`,
                    priority: 50,
                    channel: 20,
                    cold: `keep`,
                    pack: `none`,
                    capex: 1,
                    curve: 30,
                    talent: `expat`,
                    transfer: `none`,
                    shift: 0,
                    mode: `distributor`,
                    speed: `wait`,
                    gov: `none`,
                    coherence: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ln = document.getElementById(`lensInput`);
                const rt = document.getElementById(`rootInput`);
                const pr = document.getElementById(`priorityInput`);
                if (ln) decisions.lens = ln.value;
                if (rt) decisions.root = rt.value;
                if (pr) decisions.priority = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.priority) || decisions.priority < 0 || decisions.priority > 100) {
                    warn(`warn_priority_range`); return false;
                }
            } else if (round === 2) {
                const ch = document.getElementById(`channelInput`);
                const cd = document.getElementById(`coldInput`);
                const pk = document.getElementById(`packInput`);
                const cx = document.getElementById(`capexInput`);
                if (ch) decisions.channel = parseInt(ch.value, 10);
                if (cd) decisions.cold = cd.value;
                if (pk) decisions.pack = pk.value;
                if (cx) decisions.capex = parseFloat(cx.value);
                if (!Number.isFinite(decisions.channel) || decisions.channel < 0 || decisions.channel > 100) {
                    warn(`warn_channel_range`); return false;
                }
                if (!Number.isFinite(decisions.capex) || decisions.capex < 0) {
                    warn(`warn_capex_value`); return false;
                }
            } else if (round === 3) {
                const cv = document.getElementById(`curveInput`);
                const tl = document.getElementById(`talentInput`);
                const tr = document.getElementById(`transferInput`);
                const sh = document.getElementById(`shiftInput`);
                if (cv) decisions.curve = parseInt(cv.value, 10);
                if (tl) decisions.talent = tl.value;
                if (tr) decisions.transfer = tr.value;
                if (sh) decisions.shift = parseFloat(sh.value);
                if (!Number.isFinite(decisions.curve) || decisions.curve < 0 || decisions.curve > 100) {
                    warn(`warn_curve_range`); return false;
                }
                if (!Number.isFinite(decisions.shift) || decisions.shift < 0) {
                    warn(`warn_shift_value`); return false;
                }
            } else if (round === 4) {
                const md = document.getElementById(`modeInput`);
                const sp = document.getElementById(`speedInput`);
                const gv = document.getElementById(`govInput`);
                const co = document.getElementById(`coherenceInput`);
                if (md) decisions.mode = md.value;
                if (sp) decisions.speed = sp.value;
                if (gv) decisions.gov = gv.value;
                if (co) decisions.coherence = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.coherence) || decisions.coherence < 0 || decisions.coherence > 100) {
                    warn(`warn_coherence_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 — verbatim v1.0.0 composite formula, extracted so calculateResults and
            // getPerformanceSummary share one source of truth (final period == completion composite).
            const reach = Math.round(ds.reach * 10) / 10;
            const spoilage = Math.round(ds.spoilage * 10) / 10;
            const capacity = Math.round(ds.capacity);
            const contribution = Math.round(ds.contribution * 10) / 10;
            const payback = Math.round(ds.payback);
            const reachScore = Math.max(0, Math.min(100, (reach / this.INFORMAL_SHARE) * 100));
            const spoilScore = Math.max(0, Math.min(100, (30 - spoilage) / 28 * 100));
            const contribScore = Math.max(0, Math.min(100, (contribution / this.TARGET) * 100));
            return Math.round(
                reachScore * 0.22 + spoilScore * 0.20 + capacity * 0.24 + contribScore * 0.18 + payback * 0.16
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let reachDelta = 0, spoilDelta = 0, capDelta = 0, contribDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the transfer gap (Common Error 1: copy-paste execution).
                switch (d.lens) {
                    case `adapt`: capDelta += 8; contribDelta += 0.2; coachKey = `coach_r1_adapt`; break;
                    case `execution`: contribDelta -= 0.3; capDelta -= 4; coachKey = `coach_r1_execution`; break;
                    case `people`: capDelta -= 6; ds.expatTrap = true; coachKey = `coach_r1_people`; break;
                    case `market`: contribDelta -= 0.4; capDelta -= 3; coachKey = `coach_r1_market`; break;
                }

                // Rank the biggest root cause — route-to-market is the largest single source.
                switch (d.root) {
                    case `channel`: capDelta += 6; contribDelta += 0.2; if (d.lens === `adapt`) coachKey = `coach_r1_sharp`; break;
                    case `spoilage`: capDelta += 2; break;          // real, but #2 not #1
                    case `pricing`: capDelta += 1; break;            // contributes, smaller
                    case `capability`: capDelta -= 2; coachKey = `coach_r1_rootcap`; break; // a symptom, not the gap
                }

                // Weighting effort toward re-engineering the model vs. fixing execution.
                if (d.priority >= 60) { capDelta += 5; contribDelta += 0.2; }
                else if (d.priority <= 25) { capDelta -= 4; contribDelta -= 0.2; coachKey = `coach_r1_lowpriority`; }

                summaryKey = (d.lens === `adapt` && d.root === `channel`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Redesign the operating model (Common Errors 2 & 3: ignore informal channel; cold-chain denial).
                const informal = d.channel / 100;            // share routed via aggregators (reaches dukas)
                spend += d.capex;

                // Channel: reach climbs toward the 68% informal ceiling, but only if funded.
                const fundFactor = d.capex >= 5 ? 1.0 : (d.capex >= 3 ? 0.7 : 0.35);
                reachDelta += informal * (this.INFORMAL_SHARE - 11) * 0.62 * fundFactor;
                if (d.channel <= 20) { coachKey = `coach_r2_modern`; }     // still modern-trade-biased
                // Aggregators take a margin slice; too much direct caps reach.
                contribDelta += informal * 1.6 - (1 - informal) * 0.2;

                // Cold-chain strategy — keeping the full chilled portfolio with no spend is the trap.
                switch (d.cold) {
                    case `keep`:
                        spoilDelta += 0; contribDelta -= 2.0; coachKey = `coach_r2_coldkeep`;
                        break;
                    case `reformulate`:
                        spoilDelta -= 17; contribDelta += 0.6; ds.coldSolved = true;   // ambient → spoilage near Iberia, lower margin
                        break;
                    case `depots`:
                        spoilDelta -= 15; contribDelta += 1.3; spend += 2; ds.coldSolved = true; // CapEx, higher margin retained
                        break;
                    case `hybrid`:
                        spoilDelta -= 16; contribDelta += 1.5; spend += 1; ds.coldSolved = true;  // best balance
                        if (coachKey === `coach_default` || coachKey === `coach_r2_modern`) coachKey = `coach_r2_coldhybrid`;
                        break;
                }

                // Pack architecture — affordable sachets unlock the duka shelf.
                switch (d.pack) {
                    case `full`: reachDelta += 9; contribDelta += 1.0; break;
                    case `some`: reachDelta += 4; contribDelta += 0.4; break;
                    case `none`: contribDelta -= 0.5; if (coachKey === `coach_default`) coachKey = `coach_r2_packnone`; break;
                }

                // Underfunding the redesign blunts everything.
                if (d.capex <= 1) { reachDelta *= 0.7; if (coachKey === `coach_default`) coachKey = `coach_r2_underfunded`; }

                summaryKey = (d.channel >= 50 && (d.cold === `hybrid` || d.cold === `depots` || d.cold === `reformulate`) && d.pack !== `none`)
                    ? `sum_r2_good`
                    : (d.cold === `keep` ? `sum_r2_cold` : `sum_r2_weak`);
            } else if (round === 3) {
                // Build local management capacity (Common Error 4: expat dependence).
                const curve = d.curve / 100;
                spend += d.shift;

                // Localisation curve: a credible majority-local curve builds succession AND cuts expat burn.
                if (d.curve >= 60) { capDelta += 12; contribDelta += this.EXPAT_COST * 5; }
                else if (d.curve >= 35) { capDelta += 6; contribDelta += this.EXPAT_COST * 2; }
                else { capDelta -= 4; contribDelta -= this.EXPAT_COST * 3; coachKey = `coach_r3_slowcurve`; }

                // Build-vs-buy talent model.
                switch (d.talent) {
                    case `academy`: capDelta += 12; contribDelta -= 0.3; coachKey = `coach_r3_academy`; break;     // slow, durable
                    case `blend`: capDelta += 10; coachKey = `coach_r3_blend`; break;                              // lean expat core + pipeline
                    case `poach`: capDelta += 4; contribDelta -= 0.6; coachKey = `coach_r3_poach`; break;          // quick, costly, low loyalty
                    case `expat`: capDelta -= 8; contribDelta -= 1.1; ds.expatTrap = true; coachKey = `coach_r3_expat`; break; // burns budget, zero capability
                }

                // Knowledge-transfer mechanism.
                switch (d.transfer) {
                    case `structured`: capDelta += 8; break;
                    case `informal`: capDelta += 2; break;
                    case `none`: capDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_notransfer`; break;
                }

                // Shifting budget off expat salaries toward capability building.
                if (d.shift >= 3) { capDelta += 5; contribDelta += 0.3; }
                else if (d.shift <= 0) { capDelta -= 3; if (d.talent === `expat`) ds.expatTrap = true; }

                summaryKey = (d.curve >= 60 && (d.talent === `academy` || d.talent === `blend`) && d.transfer === `structured`)
                    ? `sum_r3_good`
                    : (d.talent === `expat` ? `sum_r3_expat` : `sum_r3_weak`);
            } else if (round === 4) {
                // Choose the partner and commit (Common Error 5: partner choice without alignment).
                const coherent = d.coherence / 100;
                let paybackScore = 40;   // baseline 3-year payback strength

                switch (d.mode) {
                    case `distributor`:
                        reachDelta += 14; contribDelta -= this.GAP * 0.14;        // fast reach, 14% margin given away forever
                        capDelta -= 4; paybackScore += 8; coachKey = `coach_r4_distributor`;
                        break;
                    case `jv`:
                        spend += this.JV_CAPITAL;                                  // US$7M capital
                        reachDelta += 8; contribDelta += 2.2; capDelta += 8;       // control + capability transfer
                        paybackScore += 18; coachKey = `coach_r4_jv`;
                        // JV only pays off if governed AND committed before the competitor takes the partner.
                        if (d.gov !== `full`) { contribDelta -= 1.6; capDelta -= 6; ds.partnerMisaligned = true; paybackScore -= 22; coachKey = `coach_r4_jvnogov`; }
                        if (d.speed === `wait`) { reachDelta -= 10; contribDelta -= 1.8; paybackScore -= 18; ds.partnerMisaligned = true; coachKey = `coach_r4_jvlost`; }
                        break;
                    case `hybrid`:
                        reachDelta += 11; contribDelta += 0.8; capDelta += 4;      // speed now, control later
                        paybackScore += 14; coachKey = `coach_r4_hybrid`;
                        break;
                }

                // Governance lifts any mode a little, but is decisive for the JV (handled above).
                switch (d.gov) {
                    case `full`: capDelta += 4; paybackScore += 8; break;
                    case `basic`: paybackScore += 2; break;
                    case `none`: paybackScore -= 6; if (coachKey === `coach_r4_distributor` || coachKey === `coach_r4_hybrid`) coachKey = `coach_r4_nogov`; break;
                }

                // Coherence: the 3-year P&L must reflect the model actually built in R2–R3.
                if (d.coherence >= 60) { paybackScore += 12; contribDelta += 0.6; }
                else if (d.coherence <= 25) { paybackScore -= 12; contribDelta -= 0.5; coachKey = `coach_r4_incoherent`; }

                // The financial case is only as strong as the model underneath it.
                paybackScore += (ds.coldSolved ? 8 : -10);
                paybackScore += (ds.capacity >= 55 ? 8 : (ds.capacity <= 30 ? -8 : 0));
                paybackScore = Math.max(0, Math.min(100, Math.round(paybackScore * (0.7 + 0.3 * coherent))));
                ds.payback = paybackScore;

                summaryKey = (paybackScore >= 65 && !ds.partnerMisaligned) ? `sum_r4_good` :
                             (ds.partnerMisaligned ? `sum_r4_misaligned` : `sum_r4_weak`);
            }

            // Resource accounting against the programme envelope (US$18M).
            ds.budgetUsed = Math.min(this.PROGRAMME_BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas with clamps.
            ds.reach = Math.max(0, Math.min(this.INFORMAL_SHARE + 12, Math.round((ds.reach + reachDelta) * 10) / 10));
            ds.spoilage = Math.max(2, Math.min(30, Math.round((ds.spoilage + spoilDelta) * 10) / 10));
            ds.capacity = Math.max(0, Math.min(100, Math.round(ds.capacity + capDelta)));
            ds.contribution = Math.round((ds.contribution + contribDelta) * 10) / 10;

            ds.reachHistory.push(ds.reach);
            ds.spoilHistory.push(ds.spoilage);
            ds.capHistory.push(ds.capacity);
            ds.contribHistory.push(ds.contribution);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook actually reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                reach: ds.reach,
                reachDelta: Math.round(reachDelta * 10) / 10,
                spoilage: ds.spoilage,
                spoilDelta: Math.round(spoilDelta * 10) / 10,
                capacity: ds.capacity,
                capDelta: Math.round(capDelta),
                contribution: ds.contribution,
                contribDelta: Math.round(contribDelta * 10) / 10,
                budgetUsed: ds.budgetUsed,
                payback: ds.payback,
                coldSolved: ds.coldSolved,
                expatTrap: ds.expatTrap,
                partnerMisaligned: ds.partnerMisaligned,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtUSD(v) {
            // USD reporting figures — kept visually distinct from local KSh figures.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M US$`;
            }
            return `${sign}US$${abs.toFixed(1)}M`;
        }

        _fmtPct(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            return (lang === `es` ? String(n).replace(`.`, `,`) : String(n)) + `%`;
        }

