        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const reach = Math.round(ds.reach * 10) / 10;
            const spoilage = Math.round(ds.spoilage * 10) / 10;
            const capacity = Math.round(ds.capacity);
            const contribution = Math.round(ds.contribution * 10) / 10;
            const payback = Math.round(ds.payback);

            // v1.1.0 — reuse the shared helper so the completion composite == the final period's persisted score.
            const composite = this._composite(ds);

            const reached = reach >= 45;
            const coldFixed = spoilage <= 8;
            const localised = capacity >= 60;
            const profitable = contribution >= 7.0;
            const exported = !ds.coldSolved || ds.expatTrap; // still exporting the European model

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_paused`;
            if (reached && coldFixed && localised && profitable && composite >= 75) tierKey = `grade_won`;
            else if (reached && coldFixed && localised) tierKey = `grade_fixed`;
            else if (ds.partnerMisaligned) tierKey = `grade_misaligned`;
            else if (exported) tierKey = `grade_export`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (reached && coldFixed && localised && profitable) insights.push(window.mySimulation.t(`insight_won`));
            else if (exported) insights.push(window.mySimulation.t(`insight_export`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (!coldFixed) insights.push(window.mySimulation.t(`insight_cold`));
            if (ds.expatTrap || capacity < 45) insights.push(window.mySimulation.t(`insight_expat`));
            if (reach < 35) insights.push(window.mySimulation.t(`insight_reach`));
            if (ds.partnerMisaligned) insights.push(window.mySimulation.t(`insight_partner`));
            if (reached && coldFixed && localised && profitable) insights.push(window.mySimulation.t(`insight_moat`));

            return {
                reach: reach,
                spoilage: spoilage,
                capacity: capacity,
                contribution: contribution,
                payback: payback,
                reached: reached,
                coldFixed: coldFixed,
                localised: localised,
                profitable: profitable,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="atl-cm"><p class="atl-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="atl-cm-chip ` + (ok ? `atl-cm-ok` : `atl-cm-no`) + `">` +
                `<span class="atl-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="atl-cm-kpi"><div class="atl-cm-kpi-val">` + val +
                `</div><div class="atl-cm-kpi-lbl">` + label + `</div>` +
