            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="atl-cm">` +
  `<div class="atl-cm-head">` +
    `<div class="atl-cm-score"><div class="atl-cm-score-num">` + Math.round(s.composite) +
       `<span class="atl-cm-score-den">/100</span></div>` +
       `<div class="atl-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="atl-cm-verdict"><div class="atl-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
