      kpi(t(`col_contrib`), this._fmtUSD(Number(s.contribution)), t(`cm_sub_contrib`)) +
    `</div></div>` +
  (insights ? `<div class="atl-cm-section"><div class="atl-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="atl-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
