            if (ds.spoilage >= 18 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cold`);
            if (ds.expatTrap) return window.mySimulation.t(`hint_expat`);
            if (ds.reach < 25 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_reach`);
            if (ds.partnerMisaligned) return window.mySimulation.t(`hint_partner`);
            if (ds.reach >= 45 && ds.spoilage <= 8 && ds.capacity >= 60) return window.mySimulation.t(`hint_strong`);
